{"sql":"-- Enable RLS on all tables
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channels ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.comments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channel_moderators ENABLE ROW LEVEL SECURITY;"}

{"sql":"-- Policies for users table
-- SELECT: Users can read all public user profiles (username, created_at)
CREATE POLICY users_select_public ON public.users
FOR SELECT USING (true);

-- UPDATE: Users can only modify their own profile
CREATE POLICY users_update_own ON public.users
FOR UPDATE USING (id = app_current_user_id());

-- DELETE: Users can only delete their own account
CREATE POLICY users_delete_own ON public.users
FOR DELETE USING (id = app_current_user_id());"}

{"sql":"-- Policies for channels table
-- SELECT: Everyone can read public channel information
CREATE POLICY channels_select_public ON public.channels
FOR SELECT USING (true);

-- INSERT: Any authenticated user can create a channel (becomes owner)
CREATE POLICY channels_insert_auth ON public.channels
FOR INSERT WITH CHECK (app_current_user_id() IS NOT NULL);

-- UPDATE: Only channel owners can modify channel details
CREATE POLICY channels_update_owner ON public.channels
FOR UPDATE USING (is_channel_owner(id, app_current_user_id()));

-- DELETE: Only channel owners can delete channels
CREATE POLICY channels_delete_owner ON public.channels
FOR DELETE USING (is_channel_owner(id, app_current_user_id()));"}

{"sql":"-- Policies for channel_moderators table
-- SELECT: Users can see moderator lists for channels
CREATE POLICY channel_moderators_select_all ON public.channel_moderators
FOR SELECT USING (true);

-- INSERT: Only channel owners can add moderators
CREATE POLICY channel_moderators_insert_owner ON public.channel_moderators
FOR INSERT WITH CHECK (is_channel_owner(channel_id, app_current_user_id()));

-- DELETE: Channel owners can remove moderators; moderators can remove themselves
CREATE POLICY channel_moderators_delete_owner_or_self ON public.channel_moderators
FOR DELETE USING (
  is_channel_owner(channel_id, app_current_user_id())
  OR (user_id = app_current_user_id())
);"}
